//! Galois Field $GF(2^8)$ arithmetic for DO-282B UAT Reed-Solomon decoding.
//!
//! RTCA DO-282B specifies Reed-Solomon coding over $GF(2^8)$ generated by primitive polynomial:
//! $$P(x) = x^8 + x^4 + x^3 + x^2 + 1 \quad (\mathtt{0x11D})$$
//!
//! In accordance with `docs/SPEC.md` Invariant 1 and Invariant 7, this module operates with zero
//! heap allocations on the hot path. Lookup tables are evaluated at compile time and provide
//! constant-time field multiplication, inversion, and division.

/// Primitive polynomial $P(x) = x^8 + x^4 + x^3 + x^2 + 1$ (`0x11D`).
pub const PRIMITIVE_POLYNOMIAL: u16 = 0x11D;

/// Precomputed exponent (antilog) table of size 512 for branch-free multiplication.
pub const EXP_TABLE: [u8; 512] = compute_exp_table();

/// Precomputed logarithm table mapping field elements $1$..$255$ to their discrete log base $\alpha=0x02$.
pub const LOG_TABLE: [u8; 256] = compute_log_table();

const fn compute_exp_table() -> [u8; 512] {
    let mut exp = [0u8; 512];
    let mut val = 1u16;
    let mut i = 0;
    while i < 255 {
        exp[i] = val as u8;
        exp[i + 255] = val as u8;
        val <<= 1;
        if (val & 0x100) != 0 {
            val ^= PRIMITIVE_POLYNOMIAL;
        }
        i += 1;
    }
    exp[510] = exp[0];
    exp[511] = exp[1];
    exp
}

const fn compute_log_table() -> [u8; 256] {
    let mut log = [0u8; 256];
    let mut val = 1u16;
    let mut i = 0;
    while i < 255 {
        log[val as usize] = i as u8;
        val <<= 1;
        if (val & 0x100) != 0 {
            val ^= PRIMITIVE_POLYNOMIAL;
        }
        i += 1;
    }
    log
}

/// Field addition in $GF(2^8)$ (bitwise XOR).
#[inline]
#[must_use]
pub const fn gf_add(a: u8, b: u8) -> u8 {
    a ^ b
}

/// Field subtraction in $GF(2^8)$ (identical to addition).
#[inline]
#[must_use]
pub const fn gf_sub(a: u8, b: u8) -> u8 {
    a ^ b
}

/// Field multiplication $a \cdot b$ in $GF(2^8)$ via precomputed log/antilog tables.
#[inline]
#[must_use]
pub const fn gf_mul(a: u8, b: u8) -> u8 {
    if a == 0 || b == 0 {
        0
    } else {
        let idx = LOG_TABLE[a as usize] as usize + LOG_TABLE[b as usize] as usize;
        EXP_TABLE[idx]
    }
}

/// Multiplicative inverse $a^{-1}$ in $GF(2^8)$, returning `None` if $a = 0$.
#[inline]
#[must_use]
pub const fn gf_inv(a: u8) -> Option<u8> {
    if a == 0 {
        None
    } else {
        let idx = 255 - LOG_TABLE[a as usize] as usize;
        Some(EXP_TABLE[idx])
    }
}

/// Field division $a / b$ in $GF(2^8)$, returning `None` if $b = 0$.
#[inline]
#[must_use]
pub const fn gf_div(a: u8, b: u8) -> Option<u8> {
    if b == 0 {
        None
    } else if a == 0 {
        Some(0)
    } else {
        let log_a = LOG_TABLE[a as usize] as usize;
        let log_b = LOG_TABLE[b as usize] as usize;
        let diff = (log_a + 255 - log_b) % 255;
        Some(EXP_TABLE[diff])
    }
}

/// Computes $a^{\text{power}}$ in $GF(2^8)$.
#[inline]
#[must_use]
pub const fn gf_pow(a: u8, power: usize) -> u8 {
    if a == 0 {
        0
    } else if power == 0 {
        1
    } else {
        let log_a = LOG_TABLE[a as usize] as usize;
        let idx = (log_a * (power % 255)) % 255;
        EXP_TABLE[idx]
    }
}

/// Evaluates a polynomial $P(x) = c_0 + c_1 x + \dots + c_n x^n$ at $x$ using Horner's method.
///
/// Coefficients are ordered in descending degree: `poly[0] * x^(n-1) + ... + poly[n-1]`.
#[must_use]
pub fn gf_poly_eval(poly: &[u8], x: u8) -> u8 {
    let mut acc = 0u8;
    for &coeff in poly {
        acc = gf_add(gf_mul(acc, x), coeff);
    }
    acc
}
